/* ============================================================
   OPHANIM — библейски точный ангел
   Чёрная пустота, мрамор и гравюра. Ответы персонажа — тёмный
   мрамор с крылом-глазом в углу, ваши — лист в двойной рамке.
   Пока персонаж отвечает, над полем ввода открываются глаза
   и смотрят, а у аватара загорается нимб.
   Шрифт Cormorant (SIL OFL 1.1) встроен в тему.
   Нужен Advanced Rendering.
   ============================================================ */

@font-face {
  font-family: "Cormorant Garamond";
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/cormorant-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Cormorant Garamond";
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/cormorant-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "Cormorant Garamond";
  font-style: italic;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/cormorant-italic-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Cormorant Garamond";
  font-style: italic;
  font-weight: 400 700;
  font-display: swap;
  src: url("theme/assets/cormorant-italic-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "Cormorant SC";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("theme/assets/cormorant-sc-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Cormorant SC";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("theme/assets/cormorant-sc-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

/* ---------- Анимации ---------- */

/* Глаза медленно плывут над полем ввода */
@keyframes ophanim-watch {
  0%   { background-position: 0 0; }
  100% { background-position: -320px 0; }
}

/* Нимб у аватара во время ответа */
@keyframes ophanim-halo {
  0%, 100% { box-shadow: 0 0 0 2px rgba(201, 170, 110, 0.55), 0 0 10px 2px rgba(201, 170, 110, 0.25); }
  50%      { box-shadow: 0 0 0 2px rgba(201, 170, 110, 0.9), 0 0 18px 5px rgba(201, 170, 110, 0.45); }
}

/* Холодный свет медленно скользит по мрамору */
@keyframes ophanim-light {
  0%   { background-position: left 0 top 0, -60% 0, 0 0; }
  100% { background-position: left 0 top 0, 160% 0, 0 0; }
}

/* ---------- Типографика ---------- */
.tavo-bubble-content,
.tavo-composer-input {
  font-family: "Cormorant Garamond", "Noto Serif", Georgia, serif;
}

.tavo-message-content {
  line-height: 1.55;
  font-size: 1.06em;
}

.tavo-message-content::selection,
.tavo-message-content *::selection {
  background: rgba(226, 222, 212, 0.25);
  color: inherit;
}

/* ---------- Персонаж: тёмный мрамор с крылом-глазом ---------- */
.tavo-bubble {
  border-radius: 0;
}

.tavo-character-bubble {
  background-color: #222226;
  background-image:
    url("theme/assets/wing-corner.svg"),
    linear-gradient(105deg, rgba(255, 255, 255, 0) 40%, rgba(226, 222, 212, 0.07) 50%, rgba(255, 255, 255, 0) 60%),
    url("theme/assets/marble.png");
  background-size: min(120px, 45%) auto, 50% 100%, 320px 320px;
  background-repeat: no-repeat, no-repeat, repeat;
  background-position: left 0 top 0, -60% 0, 0 0;
  border: 1px solid rgba(226, 222, 212, 0.18);
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.7);
  padding: 16px 18px 14px 22px;
  animation: ophanim-light 14s ease-in-out infinite alternate;
}

/* ---------- Вы: лист в двойной гравюрной рамке ---------- */
.tavo-user-bubble {
  background-color: rgba(11, 11, 13, 0.92);
  border: 1px solid rgba(226, 222, 212, 0.45);
  outline: 1px solid rgba(226, 222, 212, 0.18);
  outline-offset: -5px;
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.7);
  padding: 12px 16px;
}

/* ---------- Имена и аватары ---------- */
.tavo-speaker-name {
  font-family: "Cormorant SC", "Cormorant Garamond", Georgia, serif;
  font-weight: 500;
  letter-spacing: 0.14em;
  color: #e2ded4;
  font-size: 1.05em;
}

.tavo-speaker-name::before {
  content: "";
  display: inline-block;
  width: 1.3em;
  height: 0.76em;
  margin-right: 0.4em;
  vertical-align: -0.02em;
  background: url("theme/assets/eye.svg") center / contain no-repeat;
  opacity: 0.85;
}

.tavo-avatar {
  outline: 1px solid rgba(226, 222, 212, 0.55);
  outline-offset: -1px;
  filter: grayscale(1) contrast(1.08);
}

/* Пока персонаж отвечает — нимб и краски возвращаются */
:root:has(.tavo-composer-stop-icon) .tavo-character-avatar,
:root:has(.tavo-composer-stop-icon) .tavo-group-character-avatar {
  filter: grayscale(0.4);
  animation: ophanim-halo 2.6s ease-in-out infinite;
}

/* ---------- Мысли, разделитель, вложения ---------- */
.tavo-message-reasoning {
  font-style: italic;
  color: #9c9a94;
  border-left: 1px solid rgba(201, 170, 110, 0.45);
  padding-left: 10px;
}

.tavo-message-reasoning > summary {
  font-family: "Cormorant SC", Georgia, serif;
  letter-spacing: 0.1em;
  color: #c9aa6e;
}

.tavo-message-divider {
  height: 30px;
  border: 0;
  background: url("theme/assets/divider.svg") center / min(320px, 76%) auto no-repeat;
}

.tavo-message-attachments {
  filter: grayscale(1) contrast(1.05);
  outline: 1px solid rgba(226, 222, 212, 0.4);
  outline-offset: 4px;
}

.tavo-action-bar-button,
.tavo-action-bar-button-group {
  background-color: rgba(11, 11, 13, 0.85);
  border-radius: 0;
}

/* ---------- Поле ввода и глаза над ним ---------- */
.tavo-composer {
  padding-top: 32px;
  background-image: url("theme/assets/eyes-closed.png");
  background-size: 320px 30px;
  background-repeat: repeat-x;
  background-position: 0 0;
  animation: ophanim-watch 60s linear infinite;
}

/* Пока персонаж отвечает — глаза открыты и смотрят */
:root:has(.tavo-composer-stop-icon) .tavo-composer {
  background-image: url("theme/assets/eyes-open.png");
  animation-duration: 30s;
}

.tavo-composer-shell {
  background-color: rgba(11, 11, 13, 0.94);
  border: 1px solid rgba(226, 222, 212, 0.35);
  outline: 1px solid rgba(226, 222, 212, 0.12);
  outline-offset: -5px;
  border-radius: 0;
  box-shadow: 0 -6px 24px rgba(0, 0, 0, 0.6);
}

.tavo-composer-input {
  color: #e2ded4;
  caret-color: #c9aa6e;
}

.tavo-composer-input::placeholder {
  color: #77756f;
  font-style: italic;
}

.tavo-composer-send-icon,
.tavo-composer-add-icon,
.tavo-composer-voice-icon,
.tavo-composer-stop-icon {
  filter: grayscale(1) brightness(1.4);
}

@media (prefers-reduced-motion: reduce) {
  .tavo-character-bubble,
  .tavo-composer,
  :root:has(.tavo-composer-stop-icon) .tavo-composer,
  :root:has(.tavo-composer-stop-icon) .tavo-character-avatar,
  :root:has(.tavo-composer-stop-icon) .tavo-group-character-avatar {
    animation: none;
  }
}
